class Page:
    def __init__(self, v):
        self.v = v
        self.prev = None
        self.next = None


def browserHistory(home, ops):
    cur = Page(home)
    out = []
    for t, x in ops:
        if t == 0:
            n = Page(x)
            cur.next = n
            n.prev = cur
            cur = n
        elif t == 1:
            while x > 0 and cur.prev:
                cur = cur.prev
                x -= 1
        else:
            while x > 0 and cur.next:
                cur = cur.next
                x -= 1
        out.append(cur.v)
    return out
